insert:
QtObject {
id: p
property int dispMode: properties["dispMode"]
property string playTitle: properties["playTitle"]
property bool playState: properties["playState"]
property bool playerButtonEnabled: properties["playerButtonEnabled"]
property bool shuffleState: properties["shuffleState"]
property bool shuffleVisible:  properties["shuffleVisible"]
property int  repeatModeState: properties["repeatModeState"]
property bool repeatModeVisible: properties["repeatModeVisible"]
property int playTitleWidth: 480
property int playTitleHeight: 37
property int playTitleFontSize: viewstyle.textsize.L
property color playTitleFontColor: viewstyle.textcolor.L1
property int playTitleFontWeight: Font.Normal
property int playerControlBtnWidth: 110
property int playerControlBtnHeight: 110
property int sideBtnWidth: 65
property int sideBtnHeight: 110
property real maxOpacity: 1.00
property real minOpacity: 0.00
property int fadeDurationMsec: 50
}
objectName: properties["objectName"]
signal prevButtonClicked()
signal playButtonClicked()
signal nextButtonClicked()
signal prevButtonLongPressed()
signal prevButtonReleased()
signal nextButtonLongPressed()
signal nextButtonReleased()
signal shuffleButtonClicked()
signal repeatButtonClicked()
MouseArea {
anchors.fill: parent
}
Item {
id: music_title
width: title_available_area.width
height: title_available_area.height
anchors { left: parent.left; bottom: parent.bottom }
Image {
id: title_available_area
width: sourceSize.width
height: sourceSize.height
anchors { bottom: parent.bottom; left: parent.left }
source: "qrc:/panel_controller_background.png"
}
SCmnMarquee {
id: playTitleText
continuous: true
width: p.playTitleWidth
height: p.playTitleHeight
anchors {
top: parent.top; topMargin: 7
horizontalCenter: parent.horizontalCenter
}
pixelSize: p.playTitleFontSize
fontColor: p.playTitleFontColor
fontWeight: p.playTitleFontWeight
visible: basicPlayerControls.visible && (p.dispMode === 0)
isUseMarquee: true
left_mask_image_path: "qrc:/ic_audio_play_album_area_mask_left.png"
right_mask_image_path: "qrc:/ic_audio_play_album_area_mask_right.png"
onVisibleChanged: {
isUseMarquee = visible
}
}
}
Item {
id: playControl
width: none_title_image.width
height: none_title_image.height
anchors { bottom: parent.bottom; horizontalCenter: parent.horizontalCenter }
Rectangle {
id: none_title_image
width: basicPlayerControls.width
height: p.playerControlBtnHeight
anchors { bottom: parent.bottom; horizontalCenter: parent.horizontalCenter }
color: viewstyle.bgcolor.D1
}
Row {
anchors { bottom: parent.bottom; horizontalCenter: parent.horizontalCenter }
ShuffleButton
{
enable: true
width: p.sideBtnWidth
height: p.sideBtnHeight
visible: p.shuffleVisible
is_shuffle: p.shuffleState
onClicked:
{
shuffleButtonClicked()
}
}
Row {
spacing: 10
SwipeDetectionButton {
enable: p.playerButtonEnabled
width: p.playerControlBtnWidth
height: p.playerControlBtnHeight
isEnablePressAndHold: true
loadComponent: Image {
scale: 0.90
transformOrigin: Item.Center
source: "file:/opt2/appresouce/btn_audio_previous_track_normal.png"
}
pressedComponent: Image {
scale: 0.90
transformOrigin: Item.Center
source: "file:/opt2/appresouce/btn_audio_previous_track_pressed.png"
}
disableComponent: Image {
scale: 0.90
transformOrigin: Item.Center
source: "file:/opt2/appresouce/btn_audio_previous_track_disabled.png"
}
onClicked: prevButtonClicked()
onPressAndHold: prevButtonLongPressed()
onReleased: prevButtonReleased()
}
SwipeDetectionButton {
id: playButton
enable: p.playerButtonEnabled
width: p.playerControlBtnWidth
height: p.playerControlBtnHeight
loadComponent: Image {
scale: 0.86
transformOrigin: Item.Center
source: playButton.getLoadImgSource()
}
pressedComponent: Image {
scale: 0.86
transformOrigin: Item.Center
source: playButton.getPressedImgSource()
}
disableComponent: Image {
scale: 0.86
transformOrigin: Item.Center
source: playButton.getDisableImgSource()
}
onClicked: playButtonClicked()
function getLoadImgSource() {
if (false === p.playState) {
return "file:/opt2/appresouce/btn_audio_play_normal.png"
}
else{
return "file:/opt2/appresouce/btn_audio_pause_normal.png"
}
}
function getPressedImgSource() {
if (false === p.playState) {
return "file:/opt2/appresouce/btn_audio_play_pressed.png"
}
else{
return "file:/opt2/appresouce/btn_audio_pause_pressed.png"
}
}
function getDisableImgSource() {
if (false === p.playState) {
return "file:/opt2/appresouce/btn_audio_play_disabled.png"
}
else{
return "file:/opt2/appresouce/btn_audio_pause_disabled.png"
}
}
}
SwipeDetectionButton {
enable: p.playerButtonEnabled
width: p.playerControlBtnWidth
height: p.playerControlBtnHeight
isEnablePressAndHold: true
loadComponent: Image {
scale: 0.90
transformOrigin: Item.Center
source: "file:/opt2/appresouce/btn_audio_next_track_normal.png"
}
pressedComponent: Image {
scale: 0.90
transformOrigin: Item.Center
source: "file:/opt2/appresouce/btn_audio_next_track_pressed.png"
}
disableComponent: Image {
scale: 0.90
transformOrigin: Item.Center
source: "file:/opt2/appresouce/btn_audio_next_track_disabled.png"
}
onClicked: nextButtonClicked()
onPressAndHold: nextButtonLongPressed()
onReleased: nextButtonReleased()
}
}
RepeatButton
{
id: repeat
enable: true
width: p.sideBtnWidth
height: p.sideBtnHeight
visible: p.repeatModeVisible
repeat_mode: p.repeatModeState
onClicked: {
repeatButtonClicked()
}
}
}
}
states: [
State {
name: "VisibleMusicTitle"
when: p.dispMode === 0
PropertyChanges { target: basicPlayerControls; height: music_title.height}
PropertyChanges { target: playControl; enabled: true }
PropertyChanges { target: music_title; opacity: p.maxOpacity }
PropertyChanges { target: playControl; opacity: p.maxOpacity }
},
State {
name: "InVisibleMusicTitle"
when: p.dispMode === 1
PropertyChanges { target: basicPlayerControls; height: playControl.height}
PropertyChanges { target: playControl; enabled: true }
PropertyChanges { target: music_title; opacity: p.minOpacity }
PropertyChanges { target: playControl; opacity: p.maxOpacity }
},
State {
name: "InVisibleAll"
when: p.dispMode === 9
PropertyChanges { target: basicPlayerControls; height: 0 }
PropertyChanges { target: playControl; enabled: false }
PropertyChanges { target: music_title; opacity: p.minOpacity }
PropertyChanges { target: playControl; opacity: p.minOpacity }
},
State {
name: "Initial"
when: p.dispMode === 10
}
]
transitions: [
Transition {
from: "Initial"
},
Transition {
to: "VisibleMusicTitle"
NumberAnimation { target: basicPlayerControls; property: "height"; duration: 0 }
NumberAnimation { target: music_title; property: "opacity"; duration: p.fadeDurationMsec }
NumberAnimation { target: playControl; property: "opacity"; duration: p.fadeDurationMsec }
}
]
}
